buy_code:
매수 = True

if not (관심종목 == 1):
    매수 = False
elif not (데이터길이 >= {min_len}):
    매수 = False
elif {b1_start} <= 시분초 < {b1_end}:
    if 시가총액 < {b1_cap_max}:
        if not (
            등락율 >= {b1_rate_min} and 등락율 <= {b1_rate_max} and
            당일거래대금 >= {b1_day_money_min} and
            초당거래대금 >= {b1_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b1_burst_win}, 1) >= {b1_burst_mult} and
            체결강도 >= {b1_strength_min} and
            전일동시간비 >= {b1_prev_ratio_min}
        ):
            매수 = False
    else:
        매수 = False
elif {b2_start} <= 시분초 < {b2_end}:
    if {b2_cap_lo} <= 시가총액 < {b2_cap_hi}:
        if not (
            등락율 >= {b2_rate_min} and 등락율 <= {b2_rate_max} and
            당일거래대금 >= {b2_day_money_min} and
            초당거래대금 >= {b2_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b2_burst_win}, 1) >= {b2_burst_mult} and
            현재가 >= 이동평균({b2_ma_win}, 1) * {b2_ma_reclaim_mult} and
            현재가 >= 고가 * {b2_high_near_mult} and
            체결강도 >= {b2_strength_min} and
            전일동시간비 >= {b2_prev_ratio_min}
        ):
            매수 = False
    else:
        매수 = False
elif {b3_start} <= 시분초 < {b3_end}:
    if {b3_cap_lo} <= 시가총액 < {b3_cap_hi}:
        if not (
            등락율 >= {b3_rate_min} and 등락율 <= {b3_rate_max} and
            당일거래대금 >= {b3_day_money_min} and
            초당거래대금 >= {b3_sec_money_min} and
            초당거래대금 / 초당거래대금평균({b3_burst_win}, 1) >= {b3_burst_mult} and
            현재가 >= 이동평균({b3_ma_win}, 1) * {b3_ma_reclaim_mult} and
            현재가 >= 고가 * {b3_high_near_mult} and
            체결강도 >= {b3_strength_min} and
            전일동시간비 >= {b3_prev_ratio_min} and
            회전율 >= {b3_turnover_min}
        ):
            매수 = False
    else:
        매수 = False
else:
    매수 = False

if 매수:
    self.Buy()

sell_code:
매도 = False

if 수익률 >= {take_profit}:
    매도 = True
elif 수익률 <= {stop_loss}:
    매도 = True
elif 보유시간 >= {max_hold_sec}:
    매도 = True
elif 최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap}:
    매도 = True
elif 보유시간 >= {time_stop_sec} and 수익률 <= {time_stop_ret}:
    매도 = True

if 매도:
    self.Sell()
